export interface MobilidadeMake { slug: string; name: string; count: number; hasAltoValor: boolean; }
export const mobilidadeMakes: MobilidadeMake[] = (() => {
  const seen = new Map<string, MobilidadeMake>();
  for (const m of mobilidadeModels) {
    const e = seen.get(m.makeSlug);
    if (e) { e.count++; e.hasAltoValor = e.hasAltoValor || m.seloAltoValor; }
    else seen.set(m.makeSlug, { slug: m.makeSlug, name: m.make, count: 1, hasAltoValor: m.seloAltoValor });
  }
  return Array.from(seen.values());
})();

export const findMobilidadeModel = (makeSlug: string, modelSlug: string) =>
  mobilidadeModels.find((m) => m.makeSlug === makeSlug && m.modelSlug === modelSlug);

export const modelsByMake = (makeSlug: string) =>
  mobilidadeModels.filter((m) => m.makeSlug === makeSlug);
